findings.remediation:
Apply `encodeURIComponent(customerId)` in all three client methods, consistent with the encoding already applied to `featureKey` and `meterId`:

```typescript
getEntitlement<T>(customerId: string, featureKey: string): Promise<T> {
  return this.get<T>(`/api/v1/entitlements/${encodeURIComponent(customerId)}/${encodeURIComponent(featureKey)}`);
}

getUsage<T>(customerId: string, meterId: string): Promise<T> {
  return this.get<T>(`/api/v1/usage/${encodeURIComponent(customerId)}/${encodeURIComponent(meterId)}`);
}

getCredits<T>(customerId: string): Promise<T> {
  return this.get<T>(`/api/v1/credits/${encodeURIComponent(customerId)}`);
}
```
